package automation

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

const maxScheduleLookaheadYears = 8

// Vixie cron 의 표준 별칭. @reboot 은 영구 저장된 next_run_at 으로 다음 시각을 미리 정하는
// 이 스케줄러에서 뜻이 없으므로 일부러 빼 두었다.
var cronAliases = map[string]string{
	"@hourly":   "0 * * * *",
	"@daily":    "0 0 * * *",
	"@midnight": "0 0 * * *",
	"@weekly":   "0 0 * * 0",
	"@monthly":  "0 0 1 * *",
	"@yearly":   "0 0 1 1 *",
	"@annually": "0 0 1 1 *",
}

var monthNames = map[string]int{
	"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
	"JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

var weekdayNames = map[string]int{
	"SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6,
}

type cronField struct {
	allowed []bool
	// unrestricted 는 필드가 별표로 시작해 값을 제한하지 않는다는 뜻이다(`*`, `*/2`).
	unrestricted bool
}

type Schedule struct {
	Expression string
	Timezone   string
	location   *time.Location
	minute     cronField
	hour       cronField
	day        cronField
	month      cronField
	weekday    cronField
}

func ParseSchedule(expression, timezone string) (*Schedule, error) {
	expression = strings.TrimSpace(expression)
	lowered := strings.ToLower(expression)
	if alias, ok := cronAliases[lowered]; ok {
		expression = alias
	} else if strings.HasPrefix(lowered, "@") {
		// 별칭을 쓰려 한 입력에 "다섯 필드" 를 말해 주면 사용자는 다섯 필드 식을 쓴 적이 없으므로
		// 오타인지 미지원 별칭인지 구분할 수 없다. 지원 목록을 그대로 돌려준다.
		return nil, fmt.Errorf("%w: unknown schedule alias %q, supported aliases are %s", ErrInvalid, expression, strings.Join(cronAliasNames(), ", "))
	}
	parts := strings.Fields(expression)
	if len(parts) != 5 {
		return nil, fmt.Errorf("%w: schedule cron must contain five fields", ErrInvalid)
	}
	timezone = strings.TrimSpace(timezone)
	if timezone == "" {
		timezone = "UTC"
	}
	location, err := time.LoadLocation(timezone)
	if err != nil {
		return nil, fmt.Errorf("%w: unknown schedule timezone %q", ErrInvalid, timezone)
	}
	minute, err := parseCronField(parts[0], 0, 59, nil, false)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid schedule minute: %v", ErrInvalid, err)
	}
	hour, err := parseCronField(parts[1], 0, 23, nil, false)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid schedule hour: %v", ErrInvalid, err)
	}
	day, err := parseCronField(parts[2], 1, 31, nil, false)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid schedule day: %v", ErrInvalid, err)
	}
	month, err := parseCronField(parts[3], 1, 12, monthNames, false)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid schedule month: %v", ErrInvalid, err)
	}
	weekday, err := parseCronField(parts[4], 0, 7, weekdayNames, true)
	if err != nil {
		return nil, fmt.Errorf("%w: invalid schedule weekday: %v", ErrInvalid, err)
	}
	return &Schedule{Expression: strings.Join(parts, " "), Timezone: timezone, location: location, minute: minute, hour: hour, day: day, month: month, weekday: weekday}, nil
}

// cronAliasNames 는 오류 문구가 맵 순회 순서로 흔들리지 않게 지원 별칭을 정렬해 돌려준다.
func cronAliasNames() []string {
	names := make([]string, 0, len(cronAliases))
	for name := range cronAliases {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func (s *Schedule) Next(after time.Time) (time.Time, error) {
	localAfter := after.In(s.location)
	start := localAfter.Truncate(time.Minute).Add(time.Minute)
	limit := start.AddDate(maxScheduleLookaheadYears, 0, 0)
	for date := time.Date(start.Year(), start.Month(), start.Day(), 0, 0, 0, 0, s.location); date.Before(limit); date = time.Date(date.Year(), date.Month(), date.Day()+1, 0, 0, 0, 0, s.location) {
		if !s.month.allowed[int(date.Month())] || !s.matchesDay(date) {
			continue
		}
		for hour := 0; hour <= 23; hour++ {
			if !s.hour.allowed[hour] {
				continue
			}
			for minute := 0; minute <= 59; minute++ {
				if !s.minute.allowed[minute] {
					continue
				}
				candidate := time.Date(date.Year(), date.Month(), date.Day(), hour, minute, 0, 0, s.location)
				local := candidate.In(s.location)
				if local.Year() != date.Year() || local.Month() != date.Month() || local.Day() != date.Day() || local.Hour() != hour || local.Minute() != minute {
					continue
				}
				if !candidate.Before(start) && candidate.After(after) {
					return candidate.UTC(), nil
				}
			}
		}
	}
	return time.Time{}, fmt.Errorf("%w: schedule has no occurrence within %d years", ErrInvalid, maxScheduleLookaheadYears)
}

func (s *Schedule) matchesDay(date time.Time) bool {
	dayMatch := s.day.allowed[date.Day()]
	weekdayMatch := s.weekday.allowed[int(date.Weekday())]
	// crontab(5) 의 규칙: 일·요일 두 필드가 **모두 제한되어 있을 때만** 어느 한쪽이 맞으면 실행한다.
	// 한쪽이 별표로 시작하면 그 필드는 아무 날도 걸러내지 않으므로 AND 로 합쳐야 한다 —
	// 그래야 `0 0 */2 * MON` 이 "격일 중 월요일" 로 읽힌다.
	if s.day.unrestricted || s.weekday.unrestricted {
		return dayMatch && weekdayMatch
	}
	return dayMatch || weekdayMatch
}

func parseCronField(raw string, minimum, maximum int, names map[string]int, sundaySeven bool) (cronField, error) {
	// Vixie cron 은 필드 전체의 첫 글자만 보므로 `1,*/2` 처럼 다른 값이 앞서면 제한으로 남는다.
	field := cronField{allowed: make([]bool, maximum+1), unrestricted: strings.HasPrefix(raw, "*")}
	for _, segment := range strings.Split(strings.ToUpper(raw), ",") {
		segment = strings.TrimSpace(segment)
		if segment == "" {
			return cronField{}, fmt.Errorf("empty list item")
		}
		base, stepRaw, hasStep := strings.Cut(segment, "/")
		step := 1
		if hasStep {
			if strings.Contains(stepRaw, "/") {
				return cronField{}, fmt.Errorf("too many step separators")
			}
			value, err := strconv.Atoi(stepRaw)
			if err != nil || value < 1 || value > maximum-minimum+1 {
				return cronField{}, fmt.Errorf("step must be between 1 and %d", maximum-minimum+1)
			}
			step = value
		}
		start, end := minimum, maximum
		switch {
		case base == "*":
		case strings.Contains(base, "-"):
			left, right, ok := strings.Cut(base, "-")
			if !ok || strings.Contains(right, "-") {
				return cronField{}, fmt.Errorf("invalid range %q", base)
			}
			var err error
			start, err = cronValue(left, minimum, maximum, names)
			if err != nil {
				return cronField{}, err
			}
			end, err = cronValue(right, minimum, maximum, names)
			if err != nil {
				return cronField{}, err
			}
			if start > end {
				return cronField{}, fmt.Errorf("range start exceeds end")
			}
		default:
			value, err := cronValue(base, minimum, maximum, names)
			if err != nil {
				return cronField{}, err
			}
			start = value
			if !hasStep {
				end = value
			}
		}
		for value := start; value <= end; value += step {
			index := value
			if sundaySeven && value == 7 {
				index = 0
			}
			field.allowed[index] = true
		}
	}
	for _, allowed := range field.allowed {
		if allowed {
			return field, nil
		}
	}
	return cronField{}, fmt.Errorf("field selects no values")
}

func cronValue(raw string, minimum, maximum int, names map[string]int) (int, error) {
	if value, ok := names[raw]; ok {
		return value, nil
	}
	// strconv.Atoi 는 부호를 허용하므로 cron 문법에 없는 `+5`·`+0` 이 통과한다 — 값 자리는
	// 십진 숫자만이어야 하고, 아니면 같은 범위 오류로 거절한다.
	if !isDecimalDigits(raw) {
		return 0, fmt.Errorf("value %q must be between %d and %d", raw, minimum, maximum)
	}
	value, err := strconv.Atoi(raw)
	if err != nil || value < minimum || value > maximum {
		return 0, fmt.Errorf("value %q must be between %d and %d", raw, minimum, maximum)
	}
	return value, nil
}

func isDecimalDigits(raw string) bool {
	if raw == "" {
		return false
	}
	for index := 0; index < len(raw); index++ {
		if raw[index] < '0' || raw[index] > '9' {
			return false
		}
	}
	return true
}
package automation

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestScheduleNextSupportsStepsRangesNamesAndTimezone(t *testing.T) {
	schedule, err := ParseSchedule("*/15 9-17 * * MON-FRI", "Asia/Seoul")
	if err != nil {
		t.Fatal(err)
	}
	after := time.Date(2026, time.August, 3, 8, 59, 30, 0, time.FixedZone("KST", 9*60*60))
	next, err := schedule.Next(after)
	if err != nil {
		t.Fatal(err)
	}
	want := time.Date(2026, time.August, 3, 0, 0, 0, 0, time.UTC)
	if !next.Equal(want) || schedule.Expression != "*/15 9-17 * * MON-FRI" || schedule.Timezone != "Asia/Seoul" {
		t.Fatalf("next=%s schedule=%#v", next, schedule)
	}
	next, err = schedule.Next(time.Date(2026, time.August, 3, 8, 59, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	want = time.Date(2026, time.August, 4, 0, 0, 0, 0, time.UTC)
	if !next.Equal(want) {
		t.Fatalf("next workday=%s, want %s", next, want)
	}
}

func TestScheduleAliasesLeapDayAndCronDayOrSemantics(t *testing.T) {
	daily, err := ParseSchedule("@daily", "UTC")
	if err != nil || daily.Expression != "0 0 * * *" {
		t.Fatalf("daily=%#v, %v", daily, err)
	}
	leap, err := ParseSchedule("0 9 29 FEB *", "UTC")
	if err != nil {
		t.Fatal(err)
	}
	next, err := leap.Next(time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC))
	if err != nil || !next.Equal(time.Date(2028, 2, 29, 9, 0, 0, 0, time.UTC)) {
		t.Fatalf("leap next=%s, %v", next, err)
	}
	orSchedule, err := ParseSchedule("0 9 1 * MON", "UTC")
	if err != nil {
		t.Fatal(err)
	}
	next, err = orSchedule.Next(time.Date(2026, 8, 2, 12, 0, 0, 0, time.UTC))
	if err != nil || !next.Equal(time.Date(2026, 8, 3, 9, 0, 0, 0, time.UTC)) {
		t.Fatalf("cron OR next=%s, %v", next, err)
	}
	monthName, err := ParseSchedule("0 9 * JAN MON", "UTC")
	if err != nil {
		t.Fatal(err)
	}
	next, err = monthName.Next(time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC))
	if err != nil || !next.Equal(time.Date(2026, 1, 5, 9, 0, 0, 0, time.UTC)) {
		t.Fatalf("named month next=%s, %v", next, err)
	}
}

// 일·요일 두 필드를 AND 로 합칠지 OR 로 합칠지는 "두 필드가 모두 제한되어 있는가" 로 갈린다.
// 별표로 시작하는 필드(`*`, `*/2`)는 제한이 아니므로 AND 여야 한다 — 아래 표의 앞 두 사례가
// 그것을 못 박고, 나머지는 OR·한쪽 제한 사례가 함께 그대로 유지되는지 보는 대조군이다.
func TestScheduleCombinesDayAndWeekdayByRestriction(t *testing.T) {
	after := time.Date(2026, 10, 30, 12, 0, 0, 0, time.UTC)
	for _, test := range []struct {
		name       string
		expression string
		want       []string
	}{
		{
			name:       "별표 step 인 일 필드는 요일과 AND",
			expression: "0 0 */2 * MON",
			want: []string{
				"2026-11-09 Mon 00:00", "2026-11-23 Mon 00:00", "2026-12-07 Mon 00:00",
				"2026-12-21 Mon 00:00", "2027-01-11 Mon 00:00",
			},
		},
		{
			name:       "별표 step 인 요일 필드는 일과 AND",
			expression: "0 0 1 * */2",
			want: []string{
				"2026-11-01 Sun 00:00", "2026-12-01 Tue 00:00", "2027-04-01 Thu 00:00",
				"2027-05-01 Sat 00:00", "2027-06-01 Tue 00:00",
			},
		},
		{
			name:       "두 필드가 모두 제한이면 OR 로 남는다",
			expression: "0 0 1-31 * MON",
			want: []string{
				"2026-10-31 Sat 00:00", "2026-11-01 Sun 00:00", "2026-11-02 Mon 00:00",
				"2026-11-03 Tue 00:00", "2026-11-04 Wed 00:00",
			},
		},
		{
			name:       "일 필드가 별표면 요일만 본다",
			expression: "0 0 * * */3",
			want: []string{
				"2026-10-31 Sat 00:00", "2026-11-01 Sun 00:00", "2026-11-04 Wed 00:00",
				"2026-11-07 Sat 00:00", "2026-11-08 Sun 00:00",
			},
		},
		{
			name:       "요일 이름만 제한하면 그 요일에만 돈다",
			expression: "* * * * MON",
			want: []string{
				"2026-11-02 Mon 00:00", "2026-11-02 Mon 00:01", "2026-11-02 Mon 00:02",
				"2026-11-02 Mon 00:03", "2026-11-02 Mon 00:04",
			},
		},
		{
			name:       "요일 필드가 별표면 일만 본다",
			expression: "0 9 1 * *",
			want: []string{
				"2026-11-01 Sun 09:00", "2026-12-01 Tue 09:00", "2027-01-01 Fri 09:00",
				"2027-02-01 Mon 09:00", "2027-03-01 Mon 09:00",
			},
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			schedule, err := ParseSchedule(test.expression, "UTC")
			if err != nil {
				t.Fatal(err)
			}
			got := make([]string, 0, len(test.want))
			cursor := after
			for range test.want {
				next, err := schedule.Next(cursor)
				if err != nil {
					t.Fatalf("Next(%s): %v", cursor, err)
				}
				got = append(got, next.Format("2006-01-02 Mon 15:04"))
				cursor = next
			}
			for index := range test.want {
				if got[index] != test.want[index] {
					t.Fatalf("%q 다음 실행=%v, want %v", test.expression, got, test.want)
				}
			}
		})
	}
}

// 별칭은 "같은 뜻의 다섯 필드 식과 실제 실행 시각이 같은가" 로만 확인할 수 있다 —
// 맵에 문자열이 있다는 사실은 Next 가 같은 시각을 돌려준다는 증명이 아니므로
// 두 ParseSchedule 결과를 연속 4회 돌려 반환 시각을 그대로 비교한다.
func TestScheduleAliasesMatchEquivalentCronExpressions(t *testing.T) {
	after := time.Date(2026, 10, 30, 12, 34, 56, 0, time.UTC)
	for _, test := range []struct{ alias, equivalent string }{
		{"@hourly", "0 * * * *"},
		{"@daily", "0 0 * * *"},
		{"@midnight", "0 0 * * *"},
		{"@weekly", "0 0 * * 0"},
		{"@monthly", "0 0 1 * *"},
		{"@yearly", "0 0 1 1 *"},
		{"@annually", "0 0 1 1 *"},
		{"@MIDNIGHT", "0 0 * * *"},
		{"  @annually  ", "0 0 1 1 *"},
	} {
		t.Run(test.alias, func(t *testing.T) {
			aliasSchedule, err := ParseSchedule(test.alias, "UTC")
			if err != nil {
				t.Fatalf("ParseSchedule(%q): %v", test.alias, err)
			}
			plainSchedule, err := ParseSchedule(test.equivalent, "UTC")
			if err != nil {
				t.Fatal(err)
			}
			aliasRuns, plainRuns := make([]string, 0, 4), make([]string, 0, 4)
			aliasCursor, plainCursor := after, after
			for range 4 {
				aliasNext, err := aliasSchedule.Next(aliasCursor)
				if err != nil {
					t.Fatalf("alias Next(%s): %v", aliasCursor, err)
				}
				plainNext, err := plainSchedule.Next(plainCursor)
				if err != nil {
					t.Fatalf("plain Next(%s): %v", plainCursor, err)
				}
				aliasRuns = append(aliasRuns, aliasNext.Format("2006-01-02 Mon 15:04"))
				plainRuns = append(plainRuns, plainNext.Format("2006-01-02 Mon 15:04"))
				aliasCursor, plainCursor = aliasNext, plainNext
			}
			for index := range plainRuns {
				if aliasRuns[index] != plainRuns[index] {
					t.Fatalf("%q 다음 실행=%v, %q=%v", test.alias, aliasRuns, test.equivalent, plainRuns)
				}
			}
		})
	}
}

func TestScheduleSkipsNonexistentDSTWallTime(t *testing.T) {
	schedule, err := ParseSchedule("30 2 * * *", "America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	next, err := schedule.Next(time.Date(2026, 3, 8, 5, 0, 0, 0, time.UTC))
	want := time.Date(2026, 3, 9, 6, 30, 0, 0, time.UTC)
	if err != nil || !next.Equal(want) {
		t.Fatalf("DST next=%s, want %s, %v", next, want, err)
	}
}

func TestScheduleRejectsInvalidExpressions(t *testing.T) {
	for _, test := range []struct{ expression, timezone string }{
		{"* * * *", "UTC"},
		{"60 * * * *", "UTC"},
		{"*/0 * * * *", "UTC"},
		{"0 9 * * FUNDAY", "UTC"},
		{"0 9 * * *", "Mars/Base"},
		{"@reboot", "UTC"},
		{"@nope", "UTC"},
	} {
		if _, err := ParseSchedule(test.expression, test.timezone); !errors.Is(err, ErrInvalid) {
			t.Fatalf("ParseSchedule(%q,%q) error=%v", test.expression, test.timezone, err)
		}
	}
}

// cron 문법에는 부호가 없다. strconv.Atoi 는 `+5`·`-0` 을 받아들이므로 오타가 그대로
// Schedule.Expression 에 저장돼 다른 cron 구현과 사람의 눈에 읽히지 않는 식이 영구 기록으로
// 남는다. 저장 시점에 사람이 읽을 수 있는 ErrInvalid 로 돌려줘야 한다.
func TestScheduleRejectsSignedCronValues(t *testing.T) {
	for _, expression := range []string{
		"+5 0 * * *",
		"0 0 +1 +1 *",
		"0 0 1 1 +7",
		"0 0 * * +0",
		"-0 0 * * *",
		"+1-+3 0 * * *",
	} {
		t.Run(expression, func(t *testing.T) {
			schedule, err := ParseSchedule(expression, "UTC")
			if err == nil {
				next, nextErr := schedule.Next(time.Date(2026, 10, 6, 0, 0, 0, 0, time.UTC))
				t.Fatalf("ParseSchedule(%q) 가 받아들였다: expression=%q 다음 실행=%s (%v)", expression, schedule.Expression, next, nextErr)
			}
			if !errors.Is(err, ErrInvalid) {
				t.Fatalf("ParseSchedule(%q) error=%v, want ErrInvalid", expression, err)
			}
			if !strings.Contains(err.Error(), "must be between") {
